-- Forte_Dev/Suites/Api.lua
-- API presence on the LIVE client: every C_* function and global the shipped addon references
-- (Suites/ApiList.lua, generated by dev/gen_api_list.py) must exist. `hard` misses fail the suite;
-- `soft` misses (every reference is guarded in the addon) are reported in the detail only.
-- Also: the Dev addon's own needs (Screenshot, the slash table).

ForteXorcist = ForteXorcist or {}
local FX = ForteXorcist
local Dev = FX.Dev

local function exists(sym)
    local ns, fn = sym:match("^(C_%w+)%.([%w_]+)$")
    if ns then
        local ok, found = pcall(function()
            local t = _G[ns]
            return type(t) == "table" and t[fn] ~= nil
        end)
        return ok and found
    end
    return _G[sym] ~= nil
end

local function missingOf(list)
    local out = {}
    for _, sym in ipairs(list or {}) do
        if not exists(sym) then out[#out + 1] = sym end
    end
    return out
end

local function show(list)
    local parts = {}
    for i = 1, math.min(#list, 8) do parts[i] = list[i] end
    local text = table.concat(parts, ", ")
    if #list > 8 then text = text .. ", +" .. (#list - 8) .. " more" end
    return text
end

Dev.RegisterSuite("api", "ooc", function(T)
    local list = Dev.ApiList
    T.check("api: generated list present", function()
        T.truthy(type(list) == "table" and type(list.hard) == "table", "Dev.ApiList (run dev/gen_api_list.py)")
        T.note(string.format("%d files scanned, %d hard, %d soft", list.files or 0, #list.hard, #(list.soft or {})))
    end)
    if type(list) ~= "table" then return end

    T.check("api: every unguarded C_* / global the addon calls exists", function()
        local missing = missingOf(list.hard)
        T.eq(#missing, 0, #missing .. " of " .. #list.hard .. " missing: " .. show(missing))
        T.note(#list.hard .. " present")
    end)

    T.check("api: guarded references (informational)", function()
        local missing = missingOf(list.soft)
        T.note(#missing .. " of " .. #(list.soft or {}) .. " absent: " .. show(missing))
    end)

    T.check("api: the dev addon's own needs", function()
        T.eq(type(_G.Screenshot), "function", "Screenshot")
        T.eq(type(_G.SlashCmdList), "table", "SlashCmdList")
        T.eq(type(_G.issecretvalue), "function", "issecretvalue")
        T.eq(type(_G.InCombatLockdown), "function", "InCombatLockdown")
    end)
end)
